import{z as B,x as s,o as r,c as m,q as n,j as l,D as t,d as e,s as o,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"组合中的机器学习","description":"","frontmatter":{"title":"组合中的机器学习","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-ml-in-portfolio.md","filePath":"quant/pf-ml-in-portfolio.md","lastUpdated":1791413859000}'),p={name:"quant/pf-ml-in-portfolio.md"};function u(d,a,f,h,C,D){const i=s("Mermaid");return r(),m("div",null,[a[2]||(a[2]=n('<h1 id="组合中的机器学习" tabindex="-1">组合中的机器学习 <a class="header-anchor" href="#组合中的机器学习" aria-label="Permalink to &quot;组合中的机器学习&quot;">​</a></h1><div class="epigraph"><p>机器学习提高的是估计的上限，不是估计的信用；把它接进优化器的那一刻，前面十课的每一条纪律都变得更贵，也更必要。</p><footer>—— 据 Gu, Kelly and Xiu, Empirical Asset Pricing via Machine Learning, Review of Financial Studies, 2020；Grinold and Kahn, Active Portfolio Management, 2000 整理</footer></div><p><a href="/quant/pf-attribution-deep">上一课</a>把账本闭合：多期连接、层次一致、残差预算。缺口回到前端：输入优化器的 \\(\\mu\\) 与 \\(\\Sigma\\) 越来越多由机器学习生产。<a href="/quant/gkx-nn3">Gu-Kelly-Xiu 与 NN3</a>、<a href="/quant/ipca">IPCA 工具主成分</a>、<a href="/quant/autoencoder-factor-model">自编码器因子模型</a>写了估计层的方法；本课写 ML 输出变成权重这一段——接入点、病与纪律。信号研究的方法论是金融 ML 工程课程的对象，此处不重复。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个接入点各有病。其一，\\(\\mu\\)：神经网络预测的信噪比低且非平稳，直接当均值输入，优化器照单放大——第一课的误差放大机制在更糟的输入上全速运转。其二，\\(\\Sigma\\)：学习型协方差（自编码器、神经网络）不带标准误，错误的相关比错误的方向更隐蔽——它悄悄改写每一个对冲比。其三，端到端：把组合目标直接写进损失、梯度穿过优化器（可微分优化），甚至用强化学习直接学仓位——整条管线可训练的同时也整条管线可过拟合；用样本内夏普评价端到端管线，等于把黑盒搜索（第三课）的评估次数再乘上参数量。<span class="marginnote">「端到端」就是让模型从原始数据一步直出最终仓位，成本与约束不再各自成层。直觉类比：分层管线像流水线上每道工序有独立质检，端到端像一台机器包揽全部——坏在哪一环查不出来，而且整台机器可以齐心协力地过拟合同一个历史窗口。</span>错法的共同根源：ML 生产的是预测，组合消费的是持仓，中间隔着成本、约束与不确定性，省掉中间层就是把三笔账记成一笔。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是分层接入而不是端到端一步到位：估计层只生产带不确定性的预测，仓位层用轻量方法把方向与仓位解耦，验证协议原样继承信号层的防泄漏纪律，评价则必须走完整条成本链。分层的代价是放弃「一次训练直接出仓位」的便利，换来的是错误可定位——哪一层出问题，症状与修法各不相同。</p><h3 id="分层接入" tabindex="-1">分层接入 <a class="header-anchor" href="#分层接入" aria-label="Permalink to &quot;分层接入&quot;">​</a></h3><p>第一层，估计层带不确定性：\\(\\mu\\) 用集成或分位数给出分布而非点值，不确定性进入<a href="/quant/robust-portfolio-opt">稳健优化</a>或<a href="/quant/bayesian-portfolio">贝叶斯组合与参数不确定</a>的口径；\\(\\Sigma\\) 保持结构化（因子层学习、残差层解析），让错误的传播有迹可循。第二层，仓位层的轻量接入：<a href="/quant/meta-labeling">Meta-labeling</a> 把方向与仓位解耦——ML 只学「什么时候信这个信号」，不改目标函数的凸性，是性价比最高的一步；<span class="marginnote">Meta-labeling 可以读成「给信号打分」：主策略只管指方向，ML 模型只学「这个信号出现时该信几分」，输出的是仓位大小而不是买卖方向。直觉类比：老司机（主策略）负责认路开车，副驾（ML）只在颠簸路段提醒「这段慢点开」——方向盘始终在主策略手里。</span><a href="/quant/triple-barrier">Triple Barrier 标签</a>提供与持仓周期一致的监督信号。第三层，验证协议继承信号层：<a href="/quant/purge-embargo">purge-embargo</a> 与<a href="/quant/cv-leakage-finance">金融 ML 的交叉验证泄漏</a>防止时间泄漏；特征对齐 <a href="/quant/no-future-function">防止未来函数</a>；评价必须走完整条成本链——换手、容量、税后（第五课的账本），而不是停在预测误差。</p>',9)),(r(),l(A,null,{default:t(()=>[o(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22PIT%20%E7%89%B9%E5%BE%81%E4%B8%8E%E6%A0%87%E7%AD%BE%22%5D%20--%3E%20MU%5B%22mu%20%E7%9A%84%E5%88%86%E5%B8%83%E9%A2%84%E6%B5%8B%EF%BC%9A%E9%9B%86%E6%88%90%2F%E5%88%86%E4%BD%8D%E6%95%B0%22%5D%0A%20%20DATA%20--%3E%20SIG%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%20Sigma%EF%BC%9A%E5%9B%A0%E5%AD%90%E5%B1%82%E5%AD%A6%E4%B9%A0%22%5D%0A%20%20MU%20--%3E%20UNCD%5B%22%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%E8%BF%9B%E7%A8%B3%E5%81%A5%E6%88%96%E8%B4%9D%E5%8F%B6%E6%96%AF%E4%BC%98%E5%8C%96%22%5D%0A%20%20SIG%20--%3E%20UNCD%0A%20%20DATA%20--%3E%20META%5B%22Meta-labeling%EF%BC%9A%E5%8F%AA%E5%AD%A6%E4%BB%93%E4%BD%8D%22%5D%0A%20%20UNCD%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%E9%93%BE%E8%AF%84%E4%BB%B7%EF%BC%9A%E6%8D%A2%E6%89%8B%E3%80%81%E5%AE%B9%E9%87%8F%E3%80%81%E7%A8%8E%E5%90%8E%22%5D%0A%20%20META%20--%3E%20COST%0A%20%20COST%20--%3E%20GOV%5B%22%E6%A8%A1%E5%9E%8B%E5%8D%A1%E3%80%81%E7%89%88%E6%9C%AC%E4%B8%8E%E5%BD%92%E5%9B%A0%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("用基本定律定位 ML 的收益从哪来：\\(\\mathrm{IR}\\approx \\mathrm{IC}\\times\\sqrt{\\mathrm{BR}}\\times\\mathrm{TC}\\)（Grinold 与 Kahn 2000）。ML 主要抬 IC；但 ML 预测通常更高频、更分散，组合换手随之上升，转移系数 TC 被成本压低——IR 可以不升反降。所以「ML 有用」必须在权重与成本之后度量，不能停在预测层面；这是"),E("a",{href:"/quant/strategy-capacity"},"策略容量与拥挤"),e("与"),E("a",{href:"/quant/factor-decay-turnover"},"因子衰减与换手"),e("的口径在 ML 语境下的复述。端到端的诱惑为什么危险：损失函数里只写收益时，成本、约束、尾部都是「没写进去的东西」，管线会精确地找到不用付费的假凸性——把 \\(\\mu\\) 的过拟合与结构的过拟合叠成一层。校准预期用实数：Gu、Kelly 与 Xiu（2020）的样本外 \\(R^2\\) 在月度千分之几的量级——即便如此，经组合、复利与风控后仍有经济意义；这组数字既是 ML 的上限证明，也是对「端到端必然更强」幻想的最好解药。")],-1)),(r(),l(A,null,{default:t(()=>[o(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20ML%5B%22ML%20%E6%8A%AC%E9%AB%98%E9%A2%84%E6%B5%8B%E7%B2%BE%E5%BA%A6%20IC%22%5D%20--%3E%20LAW%5B%22%E5%9F%BA%E6%9C%AC%E5%AE%9A%E5%BE%8B%EF%BC%9AIR%20%E7%BA%A6%E7%AD%89%E4%BA%8E%20IC%20%C3%97%20%E6%A0%B9%E5%8F%B7%20BR%20%C3%97%20TC%22%5D%0A%20%20ML%20--%3E%20FREQ%5B%22%E9%A2%84%E6%B5%8B%E6%9B%B4%E9%AB%98%E9%A2%91%E6%9B%B4%E5%88%86%E6%95%A3%22%5D%0A%20%20FREQ%20--%3E%20TO%5B%22%E6%8D%A2%E6%89%8B%E4%B8%8A%E5%8D%87%22%5D%0A%20%20TO%20--%3E%20COST%5B%22%E4%BA%A4%E6%98%93%E6%88%90%E6%9C%AC%E5%A2%9E%E5%8A%A0%22%5D%0A%20%20COST%20--%3E%20TC%5B%22%E8%BD%AC%E7%A7%BB%E7%B3%BB%E6%95%B0%20TC%20%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20LAW%20--%3E%20NET%5B%22%E5%87%80%20IR%20%E6%9C%AA%E5%BF%85%E4%B8%8A%E5%8D%87%EF%BC%8C%E5%8F%AF%E8%83%BD%E5%8F%8D%E9%99%8D%22%5D%0A%20%20TC%20--%3E%20NET%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">IC 是预测与实现收益的相关系数，横截面上通常只有 0.02–0.05。数字实例：IC=0.03、独立下注数 BR=2000、转移系数 TC=0.3，则 IR 约 0.03 × 44.7 × 0.3 ≈ 0.40——微弱的相关乘上巨大的下注次数才凑出可用的 IR，这正是横截面策略的算术。</span></p><p><span class="marginnote">月度样本外 \\(R^2\\) 千分之几（GKX 2020 口径）听起来可怜，但它对应的是横截面数千只股票的排序信息；把它翻译成 IR，要过基本定律的三道乘法——任何一道为负，IC 的提升就到不了账上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写信号研究方法论（特征、标签、模型族谱是金融 ML 工程课程），不展开强化学习执行（执行课序的对象）；端到端可微优化的实现细节点到为止——它的正当用法是在明确的约束族内求投影，而不是把整个投资流程交给梯度。治理侧只立接口：模型卡与版本、特征的 PIT 审计、权重可解释（<a href="/quant/shap-factor-attribution">SHAP 因子归因</a>）与归因的残差预算（上一课）——ML 管线要在第 1、3、9 课的三套验收下全部过线，才有资格进组合。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三个接入点：\\(\\mu\\) 带不确定性的预测、结构化 \\(\\Sigma\\)、仓位层轻量接入；分层让错误可定位。</li><li>端到端的代价是三笔账并成一笔：预测误差、成本与约束的过拟合互相掩护。</li><li>基本定律定位 ML：IC 提升 × 换手成本 × 风险分散，任何一项倒退都吃掉收益。</li><li>验收继承信号层（purge/embargo、PIT）加组合层（成本链、税后），两套都要过。</li><li>出处：Gu, Kelly &amp; Xiu, <em>RFS</em>, 2020；Grinold &amp; Kahn, <em>Active Portfolio Management</em>, 2000；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018。</li></ul>',6))])}const g=B(p,[["render",u]]);export{T as __pageData,g as default};
